DELETE FROM Language_en_US WHERE Tag='TXT_KEY_CWC2_GUIDE_THELANTERNFLEET' OR Tag GLOB 'TXT_KEY_CWC2_GUIDE_THELANTERNFLEET_*';
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THELANTERNFLEET_CIV_HEADING_1','Playstyle and victory plan');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THELANTERNFLEET_CIV_TEXT_1','The Lantern Fleet[NEWLINE]Defensive coastal development and turn-start naval snapshots[NEWLINE]Science or Culture[NEWLINE][NEWLINE]Build useful coastal cities, keep one eligible owned military ship inside each selected city at the snapshot, and develop the ordinary economy behind those additions. A garrisoned ship has a real cost and cannot simultaneously perform every naval task.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THELANTERNFLEET_CIV_HEADING_2','Opening priorities');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THELANTERNFLEET_CIV_TEXT_2','Choose a genuinely coastal site with workable food and production. Establish a Beacon Cutter when safe and useful. The civilization does not grant a starting fleet, so shore defense and economic construction still need resources.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THELANTERNFLEET_CIV_HEADING_3','Develop the engine');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THELANTERNFLEET_CIV_TEXT_3','Place a guard in the city-centre naval slot before the qualifying turn start. Build Signal Lighthouses where their inherited coastal benefits matter. One ship is sufficient; extra parked ships do not stack more snapshot yields.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THELANTERNFLEET_CIV_HEADING_4','Convert the advantage');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THELANTERNFLEET_CIV_TEXT_4','Turn a protected coastal network into research or cultural infrastructure while retaining a mobile patrol force. Keep inland defense and naval technology current, and do not confuse guarding the city with controlling every sea lane.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THELANTERNFLEET_CIV_HEADING_5','Strengths');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THELANTERNFLEET_CIV_TEXT_5','- Eligible guarded coastal cities support a modest recurring Science/Culture plan.[NEWLINE]- Signal Lighthouses add permanent Culture and a conditional Gold incentive.[NEWLINE]- Beacon Cutters combine sight with friendly-territory combat support.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THELANTERNFLEET_CIV_HEADING_6','Weaknesses and costs');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THELANTERNFLEET_CIV_TEXT_6','- The condition needs a real coastal city and an owned naval combat unit physically in its centre.[NEWLINE]- Civilian trade ships, nearby ships and embarked land units do not qualify.[NEWLINE]- The flat additions do not scale automatically with Era, and parked guards have upkeep and opportunity costs.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THELANTERNFLEET_CIV_HEADING_7','How to play against this civilization');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THELANTERNFLEET_CIV_TEXT_7','- Pressure productive coastal approaches and landward tiles, not only the parked ship.[NEWLINE]- Use a mobile fleet to contest routes and force difficult garrison-versus-patrol decisions.[NEWLINE]- On an inland map, develop advantages that do not require coastal snapshot sites.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THELANTERNFLEET_CIV_HEADING_8','Common mistakes');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THELANTERNFLEET_CIV_TEXT_8','- Parking a ship adjacent to the city and counting it as a guard.[NEWLINE]- Counting a Cargo Ship or several stacked guards as extra qualifying copies.[NEWLINE]- Moving in after the snapshot and expecting the current turn''s conditional yields.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THELANTERNFLEET_CIV_HEADING_9','Matchup examples - conditional analysis');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THELANTERNFLEET_CIV_TEXT_9','Named custom-civilization matchups are conditional mechanical analysis, not tested win rates. All custom civs are human-only and multiplayer is unsupported; these comparisons are for theorycraft or explicitly configured scenarios, not ordinary random AI opponents. General counterplay applies to normal single-player games.[NEWLINE][NEWLINE]FAVOURABLE OPPORTUNITIES[NEWLINE][NEWLINE]Pigeon Republic: On a sea-dominated map with few safe land routes, guarded coastal sites offer opportunities Coo''s caravan-only ability cannot use.[NEWLINE][NEWLINE]The Conical Union: Separate guarded coastal sites can contribute without every city first obtaining a capital connection; the ship and Lighthouse costs still matter.[NEWLINE][NEWLINE]THREATS TO RESPECT[NEWLINE][NEWLINE]Sol Intellect: A protected mature specialist and construction engine can threaten a research race beyond the fleet''s modest flat additions.[NEWLINE][NEWLINE]Jin: Mobile land cavalry can threaten the productive approaches and resource sites beyond a parked coastal guard.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THELANTERNFLEET_CIV_HEADING_10','Implementation and timing limits');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THELANTERNFLEET_CIV_TEXT_10','Native event dispatch and exact same-turn economic settlement remain unverified acceptance requirements. The guide describes the implemented snapshot contract, not a claimed live-game timing result.');
