INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THELANTERNFLEET_LEADER_BACKGROUND','Build useful coastal cities, keep one eligible owned military ship inside each selected city at the snapshot, and develop the ordinary economy behind those additions. A garrisoned ship has a real cost and cannot simultaneously perform every naval task.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) SELECT 'TXT_KEY_CWC2_GUIDE_THELANTERNFLEET_LEADER_BACKGROUND',Text FROM Language_en_US WHERE Tag='TXT_KEY_LANTERN_LEADER_PEDIA';
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THELANTERNFLEET_STRATEGY','Build useful coastal cities, keep one eligible owned military ship inside each selected city at the snapshot, and develop the ordinary economy behind those additions. A garrisoned ship has a real cost and cannot simultaneously perform every naval task.[NEWLINE][NEWLINE]Choose a genuinely coastal site with workable food and production. Establish a Beacon Cutter when safe and useful. The civilization does not grant a starting fleet, so shore defense and economic construction still need resources.[NEWLINE][NEWLINE]Place a guard in the city-centre naval slot before the qualifying turn start. Build Signal Lighthouses where their inherited coastal benefits matter. One ship is sufficient; extra parked ships do not stack more snapshot yields.[NEWLINE][NEWLINE]Turn a protected coastal network into research or cultural infrastructure while retaining a mobile patrol force. Keep inland defense and naval technology current, and do not confuse guarding the city with controlling every sea lane.');
