INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THELANTERNFLEET_LEADER_HEADING_2','Priorities and decisions');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THELANTERNFLEET_LEADER_TEXT_2','Choose a genuinely coastal site with workable food and production. Establish a Beacon Cutter when safe and useful. The civilization does not grant a starting fleet, so shore defense and economic construction still need resources.[NEWLINE][NEWLINE]Place a guard in the city-centre naval slot before the qualifying turn start. Build Signal Lighthouses where their inherited coastal benefits matter. One ship is sufficient; extra parked ships do not stack more snapshot yields.[NEWLINE][NEWLINE]Turn a protected coastal network into research or cultural infrastructure while retaining a mobile patrol force. Keep inland defense and naval technology current, and do not confuse guarding the city with controlling every sea lane.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THELANTERNFLEET_LEADER_HEADING_3','Matchup examples - conditional analysis');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THELANTERNFLEET_LEADER_TEXT_3','Named custom-civilization matchups are conditional mechanical analysis, not tested win rates. All custom civs are human-only and multiplayer is unsupported; these comparisons are for theorycraft or explicitly configured scenarios, not ordinary random AI opponents. General counterplay applies to normal single-player games.[NEWLINE][NEWLINE]FAVOURABLE OPPORTUNITIES[NEWLINE][NEWLINE]Pigeon Republic: On a sea-dominated map with few safe land routes, guarded coastal sites offer opportunities Coo''s caravan-only ability cannot use.[NEWLINE][NEWLINE]The Conical Union: Separate guarded coastal sites can contribute without every city first obtaining a capital connection; the ship and Lighthouse costs still matter.[NEWLINE][NEWLINE]THREATS TO RESPECT[NEWLINE][NEWLINE]Sol Intellect: A protected mature specialist and construction engine can threaten a research race beyond the fleet''s modest flat additions.[NEWLINE][NEWLINE]Jin: Mobile land cavalry can threaten the productive approaches and resource sites beyond a parked coastal guard.');
